("Planned Value (PV)", "Authorized budget for the work scheduled to be done by a given date. Answers: how much work should be done by now?", ["PR.6", "PR.9"]),
("Earned Value (EV)", "Budgeted value of the work actually completed by a given date (% complete × BAC). Answers: how much work is really done?", ["PR.6", "PR.9"]),
("Actual Cost (AC)", "The cost actually incurred for the work performed by a given date.", ["PR.6", "PR.9"]),
("Budget at Completion (BAC)", "Total planned budget for all project work; the sum of all PV at the end of the project.", ["PR.6"]),
("Cost Variance (CV)", "CV = EV − AC. Negative = over budget, positive = under budget.", ["PR.6", "PR.9"]),
("Schedule Variance (SV)", "SV = EV − PV. Negative = behind schedule, positive = ahead of schedule.", ["PR.6", "PR.8", "PR.9"]),
("Cost Performance Index (CPI)", "CPI = EV / AC. Value earned per unit of money spent; < 1 means over budget.", ["PR.6", "PR.9"]),
("Schedule Performance Index (SPI)", "SPI = EV / PV. Rate of progress versus plan; < 1 means behind schedule.", ["PR.6", "PR.8", "PR.9"]),
("EAC (typical)", "EAC = BAC / CPI. Use when current cost performance is expected to continue for the remaining work.", ["PR.6", "PR.9"]),
("EAC (atypical)", "EAC = AC + (BAC − EV). Use when the variance was a one-off and the remaining work proceeds at planned rate.", ["PR.6", "PR.9"]),
("EAC (CPI and SPI)", "EAC = AC + (BAC − EV) / (CPI × SPI). Use when both cost and schedule performance will influence the remaining work.", ["PR.6", "PR.9"]),
("Estimate to Complete (ETC)", "ETC = EAC − AC. The expected cost to finish all remaining work.", ["PR.6"]),
("Variance at Completion (VAC)", "VAC = BAC − EAC. Negative = the project is forecast to finish over budget.", ["PR.6", "PR.9"]),
("To-Complete Performance Index (TCPI)", "TCPI = (BAC − EV) / (BAC − AC), or with EAC in the denominator. Cost efficiency needed on remaining work to hit the target; > 1 = harder.", ["PR.6"]),
("PERT (beta) estimate", "Three-point weighted estimate: (O + 4M + P) / 6. Emphasises the most likely value.", ["PR.8", "PR.6"]),
("Triangular estimate", "Three-point simple average: (O + M + P) / 3.", ["PR.8", "PR.6"]),
